public.crear_version_ficha.source_sql:
DECLARE
    v_new_id UUID;
    v_producto_id UUID;
    v_max_version INT;
BEGIN
    -- Obtener producto_id de la ficha original
    SELECT producto_id INTO v_producto_id
    FROM fichas_tecnicas WHERE id = p_ficha_id;

    -- Obtener máxima versión actual
    SELECT COALESCE(MAX(version), 0) INTO v_max_version
    FROM fichas_tecnicas WHERE producto_id = v_producto_id;

    -- Insertar nueva versión
    INSERT INTO fichas_tecnicas (
        producto_id, version, estado,
        descripcion_corta, descripcion_larga, bullet_points, palabras_clave,
        atributos_dinamicos, creado_por
    )
    SELECT 
        producto_id, v_max_version + 1, 'borrador',
        descripcion_corta, descripcion_larga, bullet_points, palabras_clave,
        atributos_dinamicos, p_usuario_id
    FROM fichas_tecnicas 
    WHERE id = p_ficha_id
    RETURNING id INTO v_new_id;

    RETURN v_new_id;
END;

public.aplicar_extraccion_a_ficha.source_sql:
DECLARE
    v_ficha_id UUID;
    v_extraccion JSONB;
    v_atributos_actuales JSONB;
    v_campos_aplicados INT := 0;
    v_campos_omitidos INT := 0;
    v_key TEXT;
    v_value JSONB;
BEGIN
    -- Obtener datos de la extracción
    SELECT ficha_tecnica_id, extraccion_cruda->'campos_extraidos'
    INTO v_ficha_id, v_extraccion
    FROM ficha_extracciones
    WHERE id = p_extraccion_id;

    -- Obtener atributos actuales de la ficha
    SELECT atributos_dinamicos INTO v_atributos_actuales
    FROM fichas_tecnicas WHERE id = v_ficha_id;

    -- Iterar sobre campos extraídos
    FOR v_key, v_value IN SELECT * FROM jsonb_each(v_extraccion)
    LOOP
        -- Si no existe o se permite sobrescribir
        IF NOT (v_atributos_actuales ? v_key) OR p_sobrescribir THEN
            v_atributos_actuales := v_atributos_actuales || 
                jsonb_build_object(v_key, v_value || 
                    jsonb_build_object('fecha_aplicacion', NOW(), 'aplicado_por', p_usuario_id));
            v_campos_aplicados := v_campos_aplicados + 1;
        ELSE
            v_campos_omitidos := v_campos_omitidos + 1;
        END IF;
    END LOOP;

    -- Actualizar ficha
    UPDATE fichas_tecnicas 
    SET atributos_dinamicos = v_atributos_actuales,
        fecha_actualizacion = NOW()
    WHERE id = v_ficha_id;

    -- Marcar extracción como aplicada
    UPDATE ficha_extracciones
    SET aplicada_a_ficha = TRUE,
        fecha_aplicacion = NOW(),
        aplicada_por = p_usuario_id
    WHERE id = p_extraccion_id;

    RETURN jsonb_build_object(
        'exito', TRUE,
        'campos_aplicados', v_campos_aplicados,
        'campos_omitidos', v_campos_omitidos
    );
END;

public.trigger_auditoria_ficha.source_sql:
BEGIN
    -- Cambio de estado
    IF TG_OP = 'UPDATE' AND OLD.estado IS DISTINCT FROM NEW.estado THEN
        INSERT INTO ficha_auditoria (ficha_tecnica_id, accion, campo_modificado, valor_anterior, valor_nuevo)
        VALUES (NEW.id, 'estado_cambiado', 'estado', to_jsonb(OLD.estado), to_jsonb(NEW.estado));

        -- Actualizar campos de auditoría según el nuevo estado
        CASE NEW.estado
            WHEN 'revision' THEN
                NEW.fecha_revision := NOW();
            WHEN 'aprobada' THEN
                NEW.fecha_aprobacion := NOW();
            WHEN 'publicada' THEN
                NEW.fecha_publicacion := NOW();
            ELSE NULL;
        END CASE;
    END IF;

    -- Cambio en atributos dinámicos
    IF TG_OP = 'UPDATE' AND OLD.atributos_dinamicos IS DISTINCT FROM NEW.atributos_dinamicos THEN
        INSERT INTO ficha_auditoria (ficha_tecnica_id, accion, campo_modificado, valor_anterior, valor_nuevo)
        VALUES (NEW.id, 'atributos_modificados', 'atributos_dinamicos', OLD.atributos_dinamicos, NEW.atributos_dinamicos);
    END IF;

    -- Actualizar timestamp
    NEW.fecha_actualizacion := NOW();
    NEW.updated_at := NOW();

    RETURN NEW;
END;

