public.fn_recalcular_stock.source_sql:
DECLARE
  v_disponibles INTEGER;
  v_total_ingresos INTEGER;
  v_total_egresos INTEGER;
BEGIN
  SELECT COALESCE(disponibles, 0)
  INTO v_disponibles
  FROM articulos
  WHERE articulo_id = p_articulo_id;

  SELECT COALESCE(SUM(cantidad), 0)
  INTO v_total_ingresos
  FROM ingresos
  WHERE articulo_id = p_articulo_id;

  SELECT COALESCE(SUM(cantidad), 0)
  INTO v_total_egresos
  FROM egresos
  WHERE articulo_id = p_articulo_id;

  UPDATE inventory_snapshot
  SET physical_stock = GREATEST(0, v_disponibles + v_total_ingresos - v_total_egresos),
      updated_at = NOW()
  WHERE sku = p_articulo_id;
END;

public.fn_sync_reserved_stock.source_sql:
DECLARE
  v_articulo_id TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_articulo_id := OLD.articulo_id;
  ELSE
    v_articulo_id := NEW.articulo_id;
    IF TG_OP = 'UPDATE' AND OLD.articulo_id IS DISTINCT FROM NEW.articulo_id THEN
      UPDATE inventory_snapshot
      SET reserved_stock = (
        SELECT COALESCE(SUM(cantidad), 0)
        FROM reservaciones_stock
        WHERE articulo_id = OLD.articulo_id AND estado = 'activa'
      ), updated_at = now()
      WHERE sku = OLD.articulo_id;
    END IF;
  END IF;

  UPDATE inventory_snapshot
  SET reserved_stock = (
    SELECT COALESCE(SUM(cantidad), 0)
    FROM reservaciones_stock
    WHERE articulo_id = v_articulo_id AND estado = 'activa'
  ), updated_at = now()
  WHERE sku = v_articulo_id;

  RETURN NULL;
END;

