public.trg_fn_sync_stock.source_sql:
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.articulo_id IS NOT NULL THEN
      PERFORM fn_recalcular_stock(OLD.articulo_id);
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Skip recalc if only sync_hash or appsheet_id changed
    IF (OLD.articulo_id IS NOT DISTINCT FROM NEW.articulo_id)
       AND (OLD.cantidad IS NOT DISTINCT FROM NEW.cantidad) THEN
      -- No stock-relevant change, skip
      RETURN NULL;
    END IF;
    -- articulo_id changed: recalc both old and new
    IF OLD.articulo_id IS DISTINCT FROM NEW.articulo_id THEN
      IF OLD.articulo_id IS NOT NULL THEN
        PERFORM fn_recalcular_stock(OLD.articulo_id);
      END IF;
    END IF;
    IF NEW.articulo_id IS NOT NULL THEN
      PERFORM fn_recalcular_stock(NEW.articulo_id);
    END IF;
  ELSE -- INSERT
    IF NEW.articulo_id IS NOT NULL THEN
      PERFORM fn_recalcular_stock(NEW.articulo_id);
    END IF;
  END IF;
  RETURN NULL;
END;

