public.fn_backfill_ingreso_ids.source_sql:
DECLARE
  v_item jsonb;
  v_count int;
  v_updated int := 0;
  v_no_match int := 0;
  v_ambiguous int := 0;
  v_already_set int := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_data)
  LOOP
    -- Check how many rows match
    SELECT COUNT(*) INTO v_count
    FROM ingresos
    WHERE articulo_id = v_item->>'articulo_id'
      AND cantidad = (v_item->>'cantidad')::int
      AND tipo_ingreso = v_item->>'tipo_ingreso';

    IF v_count = 0 THEN
      v_no_match := v_no_match + 1;
    ELSIF v_count > 1 THEN
      -- Try more specific match with guia
      SELECT COUNT(*) INTO v_count
      FROM ingresos
      WHERE articulo_id = v_item->>'articulo_id'
        AND cantidad = (v_item->>'cantidad')::int
        AND tipo_ingreso = v_item->>'tipo_ingreso'
        AND COALESCE(guia, '') = COALESCE(v_item->>'guia', '')
        AND ingreso_id IS NULL;

      IF v_count = 1 THEN
        UPDATE ingresos SET ingreso_id = v_item->>'ingreso_id'
        WHERE articulo_id = v_item->>'articulo_id'
          AND cantidad = (v_item->>'cantidad')::int
          AND tipo_ingreso = v_item->>'tipo_ingreso'
          AND COALESCE(guia, '') = COALESCE(v_item->>'guia', '')
          AND ingreso_id IS NULL;
        v_updated := v_updated + 1;
      ELSIF v_count = 0 THEN
        -- All matching rows already have ingreso_id
        v_already_set := v_already_set + 1;
      ELSE
        v_ambiguous := v_ambiguous + 1;
      END IF;
    ELSE
      -- Exactly 1 match
      IF (SELECT ingreso_id FROM ingresos
          WHERE articulo_id = v_item->>'articulo_id'
            AND cantidad = (v_item->>'cantidad')::int
            AND tipo_ingreso = v_item->>'tipo_ingreso'
          LIMIT 1) IS NOT NULL THEN
        v_already_set := v_already_set + 1;
      ELSE
        UPDATE ingresos SET ingreso_id = v_item->>'ingreso_id'
        WHERE articulo_id = v_item->>'articulo_id'
          AND cantidad = (v_item->>'cantidad')::int
          AND tipo_ingreso = v_item->>'tipo_ingreso'
          AND ingreso_id IS NULL;
        v_updated := v_updated + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'no_match', v_no_match,
    'ambiguous', v_ambiguous,
    'already_set', v_already_set
  );
END;

public.fn_pop_matching_job.source_sql:
DECLARE
    v_job_id uuid;
BEGIN
    SELECT id INTO v_job_id 
    FROM matching_jobs
    WHERE estado = 'pendiente'
    ORDER BY creado_el ASC
    FOR UPDATE SKIP LOCKED
    LIMIT 1;

    IF v_job_id IS NOT NULL THEN
        UPDATE matching_jobs 
        SET estado = 'corriendo', iniciado_el = now() 
        WHERE id = v_job_id;
    END IF;

    RETURN v_job_id;
END;

