public.fn_eliminar_importacion.source_sql:
DECLARE v_costos int; v_raws int; v_path text; v_bucket text;
BEGIN
  SELECT (mapeo_columnas->>'_storage_path'),
         COALESCE(mapeo_columnas->>'_bucket','excel-precios')
    INTO v_path, v_bucket
  FROM importaciones_excel WHERE id = p_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error','Importación no encontrada');
  END IF;

  DELETE FROM costos_articulo WHERE importacion_id = p_id;
  GET DIAGNOSTICS v_costos = ROW_COUNT;

  DELETE FROM listas_precios_raw WHERE importacion_id = p_id;
  GET DIAGNOSTICS v_raws = ROW_COUNT;

  DELETE FROM importaciones_excel WHERE id = p_id;

  RETURN jsonb_build_object(
    'ok', true,
    'costos_borrados', v_costos,
    'raws_borrados', v_raws,
    'storage_path', v_path,
    'storage_bucket', v_bucket
  );
END

