public.fn_watchdog_matching.source_sql:
DECLARE
    rec RECORD;
BEGIN
    -- Busca jobs colgados por más de 10 minutos
    FOR rec IN 
        SELECT id, importacion_id FROM matching_jobs 
        WHERE estado IN ('corriendo', 'pendiente') 
          AND (
             (estado = 'corriendo' AND iniciado_el < now() - interval '10 minutes')
             OR
             (estado = 'pendiente' AND creado_el < now() - interval '10 minutes')
          )
    LOOP
        UPDATE matching_jobs SET estado = 'pendiente' WHERE id = rec.id;

        INSERT INTO importacion_eventos (importacion_id, estado_paso, mensaje)
        VALUES (rec.importacion_id, 'REINTENTO_WATCHDOG', 'Watchdog detectó timeout de 10m. Reiniciando...');

        -- El trigger trg_matching_jobs_pendiente se encargará de invocar la Edge Function
    END LOOP;
END;

public.fn_disparar_edge_procesar_importa.source_sql:
DECLARE
  v_edge_url TEXT;
  v_service_key TEXT;
  req_body JSONB;
BEGIN
  SELECT value INTO v_edge_url FROM private.app_config WHERE key = 'edge_url';
  SELECT value INTO v_service_key FROM private.app_config WHERE key = 'service_role_key';

  IF v_edge_url IS NULL THEN
      v_edge_url := current_setting('app.settings.edge_url', true);
  END IF;

  IF v_service_key IS NULL THEN
      v_service_key := current_setting('app.settings.service_role_key', true);
  END IF;

  IF v_edge_url IS NOT NULL AND v_service_key IS NOT NULL THEN
     req_body := json_build_object('importacion_id', NEW.id);

     PERFORM net.http_post(
         url := v_edge_url || '/procesar-matching',
         headers := jsonb_build_object(
             'Content-Type', 'application/json',
             'Authorization', 'Bearer ' || v_service_key
         ),
         body := req_body,
         timeout_milliseconds := 10000
     );
  END IF;

  RETURN NEW;
END;

