public.fn_consolidar_importacion.source_sql:
DECLARE
    v_totales int := 0;
BEGIN
    SELECT COUNT(*) INTO v_totales FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id;

    INSERT INTO listas_precios_raw (importacion_id, proveedor, fila_num, payload, columnas_guardadas)
    SELECT importacion_id, proveedor, fila_num, payload, columnas_guardadas
    FROM listas_precios_raw_staging
    WHERE importacion_id = p_importacion_id;

    DELETE FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id;

    -- Update status
    UPDATE importaciones_excel
    SET resumen_diff = jsonb_build_object('totales', v_totales, 'nuevos', v_totales, 'modificados', 0, 'eliminados', 0)
    WHERE id = p_importacion_id;

    BEGIN
        -- Desactivar triggers de usuario temporalmente en lugar de session_replication_role
        ALTER TABLE listas_precios_proveedor DISABLE TRIGGER USER;
        ALTER TABLE costos_articulo DISABLE TRIGGER USER;

        UPDATE listas_precios_proveedor SET vigente = false WHERE proveedor = p_proveedor AND vigente = true;

        INSERT INTO listas_precios_proveedor (proveedor, importacion_id, vigente, total_filas)
        VALUES (p_proveedor, p_importacion_id, true, v_totales);

        -- Borrado lógico rápido de costos anteriores
        UPDATE costos_articulo SET vigente = false WHERE proveedor = p_proveedor AND vigente = true;

        -- Reactivar triggers
        ALTER TABLE listas_precios_proveedor ENABLE TRIGGER USER;
        ALTER TABLE costos_articulo ENABLE TRIGGER USER;
    EXCEPTION WHEN OTHERS THEN
        -- Asegurar que se reactivan incluso si hay un error
        ALTER TABLE listas_precios_proveedor ENABLE TRIGGER USER;
        ALTER TABLE costos_articulo ENABLE TRIGGER USER;
        RAISE;
    END;

    UPDATE importaciones_excel SET estado = 'completado'::estado_importacion_excel, ultima_actividad = now() WHERE id = p_importacion_id;

    INSERT INTO importacion_eventos (importacion_id, estado_paso, mensaje)
    VALUES (p_importacion_id, 'CONSOLIDADO', 'Lista de precios actualizada y costos anteriores invalidados.');
END;

public.trg_costos_articulo_recalcular.source_sql:
BEGIN
    IF NEW.articulo_id IS NOT NULL AND NEW.vigente = true THEN
        PERFORM fn_recalcular_precio_marketplace(NEW.articulo_id);
    END IF;
    RETURN NEW;
END;

public.fn_recalcular_precio_marketplace.source_sql:
DECLARE
    v_costo_base NUMERIC(12,2);
    v_rule RECORD;
    v_costo_bruto NUMERIC(12,2);
    v_subtotal NUMERIC(12,2);
    v_precio_final NUMERIC(12,2);
    v_margen_percent NUMERIC(5,2);
    v_multiplier INTEGER := 1;
BEGIN
    SELECT valor INTO v_costo_base
    FROM costos_articulo
    WHERE articulo_id = p_articulo_id AND vigente = true
    ORDER BY CASE WHEN tipo_costo ILIKE '%menudeo%' THEN 1 ELSE 2 END, valor DESC
    LIMIT 1;

    IF v_costo_base IS NULL OR v_costo_base <= 0 THEN
        RETURN;
    END IF;

    SELECT COALESCE(MAX(cantidad_requerida), 1) INTO v_multiplier
    FROM mapeo_publicacion_articulo
    WHERE articulo_id = p_articulo_id;

    v_costo_base := v_costo_base * v_multiplier;

    FOR v_rule IN (SELECT r.* FROM pricing_rules r WHERE r.is_active = true) LOOP
        v_costo_bruto := v_costo_base * (1 + (COALESCE(v_rule.tax_percentage, 0) / 100.0));
        v_subtotal := v_costo_bruto + COALESCE(v_rule.shipping_cost, 0) + COALESCE(v_rule.ml_fixed_fee, 0);

        IF v_rule.rule_type = 'margin_percentage' THEN
            v_margen_percent := v_rule.value;
            IF (v_rule.ml_commission_percentage + v_margen_percent) >= 100 THEN
                v_precio_final := v_subtotal * 2; 
            ELSE
                v_precio_final := v_subtotal / (1.0 - ((COALESCE(v_rule.ml_commission_percentage, 0) + v_margen_percent) / 100.0));
            END IF;
        ELSE
            IF COALESCE(v_rule.ml_commission_percentage, 0) >= 100 THEN
                v_precio_final := v_subtotal + v_rule.value;
            ELSE
                v_precio_final := (v_subtotal + v_rule.value) / (1.0 - (COALESCE(v_rule.ml_commission_percentage, 0) / 100.0));
            END IF;
        END IF;

        INSERT INTO marketplace_prices (articulo_id, marketplace_id, base_price, sale_price, currency)
        VALUES (p_articulo_id, v_rule.marketplace_id, v_costo_base, ROUND(v_precio_final, 2), 'MXN')
        ON CONFLICT (articulo_id, marketplace_id)
        DO UPDATE SET 
            base_price = EXCLUDED.base_price,
            sale_price = EXCLUDED.sale_price,
            updated_at = now();
    END LOOP;
END;

public.trg_recalcular_precio_publicacion.source_sql:
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  -- Para evitar invocar recursión innecesariamente
  IF NEW.sale_price_calculated IS NOT DISTINCT FROM OLD.sale_price_calculated
     AND NEW.pricing_status IS NOT DISTINCT FROM OLD.pricing_status THEN
    RETURN NEW;
  END IF;

  PERFORM fn_recalcular_precio_publicacion(NEW.id);

  RETURN NEW;
END

public.fn_recalcular_precio_publicacion.source_sql:
DECLARE
  v_pub RECORD; v_rule pricing_rule_v3; v_override RECORD;
  v_costo_base NUMERIC(12,2);
  v_commission_pct NUMERIC(5,2); v_commission_src TEXT;
  v_withholding_pct NUMERIC(5,2); v_withholding_src TEXT;
  v_denominador NUMERIC(8,4); v_numerador NUMERIC(12,2);
  v_precio_final NUMERIC(12,2);
  v_status TEXT := 'valid'; v_reason TEXT := 'OK';
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN; END IF;

  SELECT * INTO v_pub FROM publicaciones_externas WHERE id = p_publicacion_id;
  IF v_pub IS NULL THEN RETURN; END IF;

  SELECT * INTO v_override
  FROM publication_pricing_overrides
  WHERE publicacion_id = p_publicacion_id
    AND (valido_hasta IS NULL OR valido_hasta > now());

  IF v_override IS NOT NULL AND v_override.override_type = 'force_rule' THEN
    SELECT * INTO v_rule FROM pricing_rule_v3 WHERE id = v_override.force_rule_id;
    v_reason := 'override_force_rule';
  ELSE
    v_rule := fn_resolver_regla_pricing(p_publicacion_id);
    IF v_rule IS NULL THEN
      UPDATE publicaciones_externas SET pricing_status='no_rule', last_calc_at=now() WHERE id=p_publicacion_id;
      RETURN;
    END IF;
  END IF;

  WITH costo_unico AS (
    SELECT DISTINCT ON (c.articulo_id) c.articulo_id, c.valor
    FROM costos_articulo c
    WHERE c.vigente = true AND c.valor > 0
      AND lower(c.tipo_costo) = lower(v_rule.cost_basis)
    ORDER BY c.articulo_id, c.creado_el DESC
  )
  SELECT SUM(cu.valor * m.cantidad_requerida) INTO v_costo_base
  FROM mapeo_publicacion_articulo m
  JOIN costo_unico cu ON cu.articulo_id = m.articulo_id
  WHERE m.publicacion_id = p_publicacion_id;

  IF v_costo_base IS NULL OR v_costo_base <= 0 THEN
    UPDATE publicaciones_externas
       SET pricing_status='missing_cost', last_calc_at=now()
     WHERE id=p_publicacion_id;
    RETURN;
  END IF;

  SELECT commission_effective, commission_source,
         withholding_effective, withholding_source
    INTO v_commission_pct, v_commission_src,
         v_withholding_pct, v_withholding_src
  FROM v_category_pricing_params
  WHERE category_id = v_pub.category_id;

  IF v_commission_pct IS NULL THEN
    v_commission_pct  := 16.0; v_commission_src := 'fallback_global';
    v_withholding_pct := 8.0;  v_withholding_src:= 'fallback_global';
    v_status := 'estimated_params';
  END IF;

  IF v_override IS NOT NULL THEN
    IF v_override.override_type = 'fixed_price' THEN
      v_precio_final := v_override.value;
      v_reason := 'override_fixed_price';
      v_status := 'override_active';
    ELSIF v_override.override_type = 'custom_margin' THEN
      v_rule.margen_objetivo := v_override.value;
      v_reason := 'override_margin';
    END IF;
  END IF;

  IF v_status NOT IN ('override_active', 'override') THEN
    v_numerador := v_costo_base * (1 + v_rule.margen_objetivo / 100.0)
                 + COALESCE(v_rule.envio_fijo, 0);
    v_denominador := 1.0 - (v_commission_pct + v_withholding_pct) / 100.0;

    IF v_denominador <= 0 THEN
      UPDATE publicaciones_externas
         SET pricing_status='invalid_strategy',
             last_calc_at=now()
       WHERE id=p_publicacion_id;
      RETURN;
    END IF;

    v_precio_final := v_numerador / v_denominador;

    v_precio_final := CASE v_rule.redondeo
      WHEN '99' THEN FLOOR(v_precio_final / 10) * 10 + 9
      WHEN '00' THEN ROUND(v_precio_final / 10) * 10
      WHEN '5'  THEN ROUND(v_precio_final / 5)  * 5
      ELSE ROUND(v_precio_final, 2)
    END;
  END IF;

  UPDATE publicaciones_externas
     SET sale_price_calculated = v_precio_final,
         pricing_status = v_status,
         last_calc_at = now()
   WHERE id = p_publicacion_id;

  INSERT INTO publication_pricing_history(
    publicacion_id, old_price, new_price, status, reason, details, created_at)
  VALUES (
    p_publicacion_id, v_pub.sale_price_calculated, v_precio_final, v_status, v_reason,
    jsonb_build_object(
      'costo_base', v_costo_base,
      'cost_basis', v_rule.cost_basis,
      'margen_pct', v_rule.margen_objetivo,
      'comision_pct', v_commission_pct, 'comision_src', v_commission_src,
      'retenciones_pct', v_withholding_pct, 'retenciones_src', v_withholding_src,
      'envio_fijo', v_rule.envio_fijo,
      'rule_id', v_rule.id, 'rule_name', v_rule.name,
      'override_aplicado', (v_override IS NOT NULL)
    ), now());
END

public.fn_parse_precio.source_sql:
DECLARE
    v_clean text;
BEGIN
    IF p_text IS NULL OR trim(p_text) = '' THEN
        RETURN NULL;
    END IF;
    -- Quitar espacios, comas y signos de dólar
    v_clean := regexp_replace(p_text, '[$\s,]', '', 'g');
    -- Manejar paréntesis para negativos ej: (10.50) -> -10.50
    IF v_clean LIKE '(%)' THEN
        v_clean := '-' || substring(v_clean from 2 for length(v_clean) - 2);
    END IF;
    RETURN v_clean::numeric;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;

public.fn_confirmar_matching_decisiones.source_sql:
DECLARE
  _confirmadas int := 0;
  _alias_pre   int;
  _alias_post  int;
BEGIN
  -- 1) Marcar confirmadas con su articulo_id_final
  WITH payload AS (
    SELECT (e->>'id')::uuid          AS id,
           NULLIF(e->>'articulo_id','') AS articulo_id
    FROM jsonb_array_elements(_decisiones) e
  )
  UPDATE public.matching_decisiones md
     SET confirmado          = true,
         articulo_id_final   = p.articulo_id,
         confirmado_at       = now()
    FROM payload p
   WHERE md.id = p.id
     AND md.importacion_id = _importacion_id;
  GET DIAGNOSTICS _confirmadas = ROW_COUNT;

  -- 2) Disparar la consolidación (UPSERT al diccionario + propagación de costos)
  SELECT COUNT(*) INTO _alias_pre  FROM public.proveedor_articulos_alias;
  PERFORM public.fn_consolidar_matching_decisiones(_importacion_id);
  SELECT COUNT(*) INTO _alias_post FROM public.proveedor_articulos_alias;

  RETURN QUERY SELECT _confirmadas, (_alias_post - _alias_pre);
END

public.fn_calcular_precio_publico.source_sql:
DECLARE
    v_costo numeric;
    v_margen numeric;
    v_retenciones numeric := 0;
    v_fijos numeric := 0;
    v_ret jsonb;
    v_elem jsonb;
    v_precio_final numeric;
BEGIN
    -- Obtener costo base: preferir costo vigente
    SELECT valor INTO v_costo 
    FROM costos_articulo 
    WHERE articulo_id = p_articulo_id AND vigente = true 
    ORDER BY tipo_costo ASC LIMIT 1;

    IF v_costo IS NULL THEN
        RETURN NULL;
    END IF;

    -- Obtener parametros de la regla
    SELECT margen_pct, retenciones, costos_fijos 
    INTO v_margen, v_ret, v_fijos
    FROM reglas_precio WHERE id = p_regla_id;

    -- Sumar retenciones porcentuales
    IF v_ret IS NOT NULL AND jsonb_typeof(v_ret) = 'array' THEN
        FOR v_elem IN SELECT * FROM jsonb_array_elements(v_ret)
        LOOP
            v_retenciones := v_retenciones + COALESCE((v_elem->>'porcentaje')::numeric, 0);
        END LOOP;
    END IF;

    -- Formula inversa: precio = (costo + fijos) / (1 - margen% - retenciones%)
    IF (1 - (v_margen / 100.0) - (v_retenciones / 100.0)) <= 0 THEN
        RETURN v_costo + v_fijos; -- Fallback para evitar divisor 0 o negativo
    END IF;

    v_precio_final := (v_costo + v_fijos) / (1 - (v_margen / 100.0) - (v_retenciones / 100.0));
    RETURN round(v_precio_final, 2);
END;

public.update_actualizado_el.source_sql:
BEGIN
    NEW.actualizado_el = now();
    RETURN NEW;
END;

public.fn_match_precios_v2.source_sql:
DECLARE
    v_mapeo jsonb;
    v_col_modelo text;
    v_col_marca text;
    v_col_codigo text;
    v_col_nombre text;
    v_col_moneda text;
    v_moneda_default text;
    v_proveedor text;
    v_job_id uuid;
    v_total_filas int;
BEGIN
    SELECT mapeo_columnas, proveedor, total_filas INTO v_mapeo, v_proveedor, v_total_filas
    FROM importaciones_excel WHERE id = p_importacion_id;

    PERFORM pg_advisory_xact_lock(hashtext('precio_import_' || v_proveedor));

    SELECT id INTO v_job_id FROM matching_jobs WHERE importacion_id = p_importacion_id LIMIT 1;
    IF v_job_id IS NOT NULL THEN
        UPDATE matching_jobs SET estado = 'corriendo', iniciado_el = now(), total = v_total_filas WHERE id = v_job_id;
    END IF;

    v_col_modelo := v_mapeo->>'columna_modelo';
    v_col_marca := v_mapeo->>'columna_marca';
    v_col_codigo := v_mapeo->>'columna_codigo';
    v_col_nombre := v_mapeo->>'columna_descripcion';
    v_col_moneda := v_mapeo->>'columna_moneda';
    v_moneda_default := COALESCE(v_mapeo->>'moneda_default', 'MXN');

    DROP TABLE IF EXISTS tmp_excel;
    CREATE TEMP TABLE tmp_excel ON COMMIT DROP AS
    SELECT regexp_replace(COALESCE(payload->>v_col_codigo, ''), '[^0-9A-Za-z]', '', 'g') AS codigo_excel,
           COALESCE(payload->>v_col_marca, '') AS marca_excel,
           COALESCE(payload->>v_col_modelo, '') AS modelo_excel,
           COALESCE(payload->>v_col_nombre, '') AS nombre_excel,
           COALESCE(payload->>v_col_moneda, v_moneda_default) AS moneda_excel,
           payload, fila_num
    FROM listas_precios_raw   -- <--- CORRECCION: Lee del historico, ya no del staging vacio
    WHERE importacion_id = p_importacion_id;

    DROP TABLE IF EXISTS tmp_resolucion;
    CREATE TEMP TABLE tmp_resolucion ON COMMIT DROP AS
    WITH e AS (SELECT * FROM tmp_excel),
    md_match AS (
        SELECT e.fila_num, md.cand_articulo_id
        FROM e
        JOIN matching_decisiones md ON md.importacion_id = p_importacion_id
            AND md.codigo_universal_excel = e.codigo_excel
            AND md.marca_excel = e.marca_excel
            AND md.modelo_excel = e.modelo_excel
            AND md.confirmado = true
    ),
    a1_match AS (
        SELECT e.fila_num, a1.articulo_id
        FROM e
        JOIN proveedor_articulos_alias a1 ON a1.proveedor = v_proveedor AND a1.codigo_excel = e.codigo_excel
        WHERE e.codigo_excel <> ''
    ),
    a2_match AS (
        SELECT e.fila_num, a2.articulo_id
        FROM e
        JOIN proveedor_articulos_alias a2 ON a2.proveedor = v_proveedor AND a2.marca_excel = e.marca_excel AND a2.modelo_excel = e.modelo_excel
        WHERE e.codigo_excel = ''
    ),
    a3_match AS (
        SELECT e.fila_num, a3.articulo_id
        FROM e
        JOIN articulos a3 ON lower(public.f_unaccent_immutable(trim(a3.codigo_universal))) = lower(public.f_unaccent_immutable(trim(e.codigo_excel)))
        WHERE e.codigo_excel <> '' AND a3.activo = true
    )
    SELECT e.*, COALESCE(md.cand_articulo_id, a1.articulo_id, a2.articulo_id, a3.articulo_id) AS articulo_id_resuelto
    FROM e
    LEFT JOIN (SELECT fila_num, MIN(cand_articulo_id) AS cand_articulo_id FROM md_match GROUP BY fila_num) md ON md.fila_num = e.fila_num
    LEFT JOIN (SELECT fila_num, MIN(articulo_id) AS articulo_id FROM a1_match GROUP BY fila_num) a1 ON a1.fila_num = e.fila_num
    LEFT JOIN (SELECT fila_num, MIN(articulo_id) AS articulo_id FROM a2_match GROUP BY fila_num) a2 ON a2.fila_num = e.fila_num
    LEFT JOIN (SELECT fila_num, MIN(articulo_id) AS articulo_id FROM a3_match GROUP BY fila_num) a3 ON a3.fila_num = e.fila_num;

    WITH precios_expandidos AS (
        SELECT t.codigo_excel, t.marca_excel, t.modelo_excel, t.nombre_excel, t.moneda_excel, t.articulo_id_resuelto, t.fila_num,
               p->>'tipo_costo' AS tipo_costo, fn_parse_precio(t.payload->>(p->>'columna')) AS valor,
               COALESCE((p->>'incluye_iva')::boolean, false) AS incluye_iva
        FROM tmp_resolucion t, jsonb_array_elements(v_mapeo->'precios') AS p
    ),
    dedup AS (
        SELECT DISTINCT ON (articulo_id_resuelto, tipo_costo) pe.*
        FROM precios_expandidos pe
        WHERE pe.valor IS NOT NULL AND pe.articulo_id_resuelto IS NOT NULL
        ORDER BY articulo_id_resuelto, tipo_costo, fila_num DESC
    )
    INSERT INTO costos_articulo (
        importacion_id, articulo_id, articulo_sugerido_id, modelo_excel, marca_excel, codigo_universal_excel,
        descripcion_excel, nombre_excel, tipo_costo, valor, moneda, fuente, puntaje_match, estado_match, vigente, incluye_iva
    )
    SELECT p_importacion_id, d.articulo_id_resuelto, d.articulo_id_resuelto, d.modelo_excel, d.marca_excel, d.codigo_excel,
           d.nombre_excel, d.nombre_excel, d.tipo_costo, d.valor, d.moneda_excel, 'excel', 100, 'match_exacto', true, d.incluye_iva
    FROM dedup d
    ON CONFLICT (articulo_id, tipo_costo, fuente) DO UPDATE
    SET valor = EXCLUDED.valor, moneda = EXCLUDED.moneda, importacion_id = EXCLUDED.importacion_id,
        vigente = EXCLUDED.vigente, actualizado_el = now(), incluye_iva = EXCLUDED.incluye_iva;

    WITH precios_expandidos AS (
        SELECT t.codigo_excel, t.marca_excel, t.modelo_excel, t.nombre_excel, t.moneda_excel, t.articulo_id_resuelto, t.fila_num,
               p->>'tipo_costo' AS tipo_costo, fn_parse_precio(t.payload->>(p->>'columna')) AS valor
        FROM tmp_resolucion t, jsonb_array_elements(v_mapeo->'precios') AS p
    ),
    dedup_pend AS (
        SELECT DISTINCT ON (COALESCE(codigo_excel,''), COALESCE(marca_excel,''), COALESCE(modelo_excel,''), tipo_costo) pe.*
        FROM precios_expandidos pe
        WHERE pe.valor IS NOT NULL AND pe.articulo_id_resuelto IS NULL
        ORDER BY COALESCE(codigo_excel,''), COALESCE(marca_excel,''), COALESCE(modelo_excel,''), tipo_costo, fila_num DESC
    )
    INSERT INTO costos_pendientes (
        importacion_id, proveedor, codigo_excel, marca_excel, modelo_excel, tipo_costo, moneda, valor, motivo
    )
    SELECT p_importacion_id, v_proveedor, d.codigo_excel, d.marca_excel, d.modelo_excel, d.tipo_costo, d.moneda_excel, d.valor, 'sin_match'
    FROM dedup_pend d
    ON CONFLICT (proveedor, COALESCE(codigo_excel,''), COALESCE(marca_excel,''), COALESCE(modelo_excel,''), tipo_costo)
    WHERE resuelto = false
    DO UPDATE SET valor = EXCLUDED.valor, importacion_id = EXCLUDED.importacion_id, actualizado_el = now();

    DELETE FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id;

    IF p_finalizar THEN
        UPDATE proveedor_articulos_alias SET estado_proveedor = 'descontinuado' WHERE proveedor = v_proveedor AND ultima_vez_visto < (now() - interval '1 day');
        PERFORM fn_marcar_vigente(p_importacion_id);
        IF v_job_id IS NOT NULL THEN
            UPDATE matching_jobs SET estado = 'completado', progreso = v_total_filas, finalizado_el = now() WHERE id = v_job_id;
        END IF;
        UPDATE importaciones_excel SET estado = 'completado', ultima_actividad = now() WHERE id = p_importacion_id;
    ELSE
        UPDATE importaciones_excel SET estado = 'procesando', ultima_actividad = now() WHERE id = p_importacion_id;
    END IF;
END;

public.vincular_ficha.source_sql:
BEGIN
  IF NOT EXISTS (SELECT 1 FROM fichas_tecnicas WHERE id = p_ficha_id) THEN
    RAISE EXCEPTION 'Ficha % no existe', p_ficha_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM articulos WHERE articulo_id = p_articulo_id) THEN
    RAISE EXCEPTION 'Articulo % no existe en catalogo', p_articulo_id;
  END IF;
  UPDATE fichas_tecnicas SET articulo_id = p_articulo_id WHERE id = p_ficha_id;
  RETURN jsonb_build_object('ok', true, 'ficha_id', p_ficha_id, 'articulo_id', p_articulo_id);
END;

public.desvincular_ficha.source_sql:
BEGIN
  IF NOT EXISTS (SELECT 1 FROM fichas_tecnicas WHERE id = p_ficha_id) THEN
    RAISE EXCEPTION 'Ficha % no existe', p_ficha_id;
  END IF;
  UPDATE fichas_tecnicas SET articulo_id = NULL WHERE id = p_ficha_id;
  RETURN jsonb_build_object('ok', true, 'ficha_id', p_ficha_id, 'articulo_id', null);
END;

public.eliminar_ficha_completa.source_sql:
DECLARE
  v_extracciones int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM fichas_tecnicas WHERE id = p_ficha_id) THEN
    RAISE EXCEPTION 'Ficha % no existe', p_ficha_id;
  END IF;
  DELETE FROM ficha_extracciones WHERE ficha_tecnica_id = p_ficha_id;
  GET DIAGNOSTICS v_extracciones = ROW_COUNT;
  DELETE FROM fichas_tecnicas WHERE id = p_ficha_id;
  RETURN jsonb_build_object('ok', true, 'ficha_id', p_ficha_id, 'extracciones_eliminadas', v_extracciones);
END;

public.desvincular_ficha_articulo.source_sql:
DECLARE
  v_old_articulo text;
BEGIN
  -- Obtener articulo_id actual para log
  SELECT articulo_id INTO v_old_articulo
  FROM fichas_tecnicas WHERE id = p_ficha_id;

  IF v_old_articulo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La ficha no tiene artículo vinculado');
  END IF;

  -- Solo desvincula la referencia al catálogo
  -- Los campos propios (marca, modelo, variante, etc.) NO se tocan
  UPDATE fichas_tecnicas
  SET
    articulo_id = NULL,
    updated_at = now()
  WHERE id = p_ficha_id;

  RETURN jsonb_build_object(
    'ok', true,
    'desvinculado', v_old_articulo,
    'nota', 'Identidad del producto preservada en columnas propias'
  );
END;

public.fn_validar_transicion_estado_impo.source_sql:
BEGIN
  IF NEW.estado = OLD.estado THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM importacion_estado_transiciones WHERE desde = OLD.estado AND hasta = NEW.estado) THEN
    RAISE EXCEPTION 'Transicion invalida de % a % en importaciones_excel id=%', OLD.estado, NEW.estado, OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END

public.eliminar_ficha_borrador.source_sql:
DECLARE
  v_ficha RECORD;
  v_extracciones_deleted INT;
BEGIN
  SELECT id, estado, nombre_producto, articulo_id
  INTO v_ficha
  FROM fichas_tecnicas
  WHERE id = p_ficha_id;
  
  IF NOT FOUND THEN
    RETURN json_build_object('ok', false, 'error', 'Ficha no encontrada');
  END IF;
  
  IF v_ficha.estado = 'publicada' THEN
    RETURN json_build_object('ok', false, 'error', 'No se puede eliminar una ficha publicada. Cambiala a borrador primero.');
  END IF;
  
  -- Eliminar extracciones hijas
  DELETE FROM ficha_extracciones
  WHERE ficha_tecnica_id = p_ficha_id;
  GET DIAGNOSTICS v_extracciones_deleted = ROW_COUNT;
  
  -- Eliminar la ficha
  DELETE FROM fichas_tecnicas
  WHERE id = p_ficha_id;
  
  RETURN json_build_object(
    'ok', true,
    'ficha_id', p_ficha_id,
    'nombre', v_ficha.nombre_producto,
    'extracciones_eliminadas', v_extracciones_deleted
  );
END;

public.fn_backfill_egreso_ids.source_sql:
DECLARE
  v_item jsonb;
  v_count int;
  v_updated int := 0;
  v_no_match int := 0;
  v_ambiguous int := 0;
  v_already_set int := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_data)
  LOOP
    SELECT COUNT(*) INTO v_count
    FROM egresos
    WHERE articulo_id = v_item->>'articulo_id'
      AND cantidad = (v_item->>'cantidad')::int
      AND tipo_egreso = v_item->>'tipo_egreso'
      AND COALESCE(guia, '') = COALESCE(v_item->>'guia', '')
      AND egreso_id IS NULL;

    IF v_count = 1 THEN
      UPDATE egresos SET egreso_id = v_item->>'egreso_id'
      WHERE articulo_id = v_item->>'articulo_id'
        AND cantidad = (v_item->>'cantidad')::int
        AND tipo_egreso = v_item->>'tipo_egreso'
        AND COALESCE(guia, '') = COALESCE(v_item->>'guia', '')
        AND egreso_id IS NULL;
      v_updated := v_updated + 1;
    ELSIF v_count = 0 THEN
      SELECT COUNT(*) INTO v_count
      FROM egresos
      WHERE articulo_id = v_item->>'articulo_id'
        AND cantidad = (v_item->>'cantidad')::int
        AND tipo_egreso = v_item->>'tipo_egreso'
        AND COALESCE(guia, '') = COALESCE(v_item->>'guia', '')
        AND egreso_id IS NOT NULL;
      IF v_count > 0 THEN
        v_already_set := v_already_set + 1;
      ELSE
        v_no_match := v_no_match + 1;
      END IF;
    ELSE
      v_ambiguous := v_ambiguous + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'no_match', v_no_match,
    'ambiguous', v_ambiguous,
    'already_set', v_already_set
  );
END;

public.fn_watchdog_importaciones.source_sql:
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN 
        SELECT id, estado, ultima_actividad FROM importaciones_excel 
        WHERE estado IN ('mapeando', 'procesando') 
          AND ultima_actividad < now() - interval '30 minutes'
    LOOP
        UPDATE importaciones_excel SET estado = 'error', error_mensaje = 'Timeout: El proceso tomó demasiado tiempo o se colgó.' WHERE id = rec.id;

        BEGIN
            ALTER TABLE listas_precios_raw DISABLE TRIGGER USER;
            ALTER TABLE costos_articulo DISABLE TRIGGER USER;
            ALTER TABLE matching_jobs DISABLE TRIGGER USER;

            DELETE FROM listas_precios_raw WHERE importacion_id = rec.id;
            DELETE FROM listas_precios_raw_staging WHERE importacion_id = rec.id;
            DELETE FROM costos_articulo WHERE importacion_id = rec.id;
            DELETE FROM matching_jobs WHERE importacion_id = rec.id;

            ALTER TABLE listas_precios_raw ENABLE TRIGGER USER;
            ALTER TABLE costos_articulo ENABLE TRIGGER USER;
            ALTER TABLE matching_jobs ENABLE TRIGGER USER;
        EXCEPTION WHEN OTHERS THEN
            ALTER TABLE listas_precios_raw ENABLE TRIGGER USER;
            ALTER TABLE costos_articulo ENABLE TRIGGER USER;
            ALTER TABLE matching_jobs ENABLE TRIGGER USER;
            RAISE;
        END;

        INSERT INTO importacion_eventos (importacion_id, estado_paso, mensaje)
        VALUES (rec.id, 'WATCHDOG', 'Cancelada y limpiada automáticamente por inactividad.');
    END LOOP;
END;

public.fn_revertir_importacion.source_sql:
DECLARE
    v_proveedor text;
BEGIN
    SELECT proveedor INTO v_proveedor FROM importaciones_excel WHERE id = p_importacion_id;
    IF v_proveedor IS NULL THEN
        RAISE EXCEPTION 'Importación no encontrada';
    END IF;

    -- Eliminar los costos generados por esta importacion
    DELETE FROM costos_articulo WHERE importacion_id = p_importacion_id;

    -- Eliminar los pendientes generados por esta importacion
    DELETE FROM costos_pendientes WHERE importacion_id = p_importacion_id;

    -- Activar la lista anterior más reciente del proveedor
    UPDATE listas_precios_proveedor
    SET vigente = true, fecha_vigor_hasta = NULL
    WHERE id = (
        SELECT id FROM listas_precios_proveedor 
        WHERE proveedor = v_proveedor AND importacion_id <> p_importacion_id
        ORDER BY importacion_fecha DESC LIMIT 1
    );

    UPDATE importaciones_excel SET estado = 'revertido', ultima_actividad = now() WHERE id = p_importacion_id;

    -- Encolar recalculo masivo de los articulos afectados si tenian precio basado en esta importacion
    INSERT INTO precio_recalc_queue (articulo_id)
    SELECT DISTINCT articulo_id FROM costos_articulo WHERE proveedor = v_proveedor
    ON CONFLICT DO NOTHING;
END;

public.fn_marcar_vigente.source_sql:
DECLARE
    v_proveedor text;
    v_total_filas_nuevo int;
    v_total_filas_actual int;
    v_importacion_id_actual uuid;
BEGIN
    SELECT proveedor, total_filas INTO v_proveedor, v_total_filas_nuevo 
    FROM importaciones_excel WHERE id = p_importacion_id;

    -- Obtener la importación vigente actual
    SELECT importacion_id, total_filas INTO v_importacion_id_actual, v_total_filas_actual
    FROM public.listas_precios_proveedor
    WHERE proveedor = v_proveedor AND vigente = true
    LIMIT 1;

    -- Candado anti-pruebas: Si la nueva lista tiene menos del 50% de las filas de la lista actual, NO promover automáticamente.
    IF v_total_filas_actual IS NOT NULL AND v_total_filas_nuevo < (v_total_filas_actual * 0.5) THEN
        RAISE NOTICE 'No se promueve la lista % porque tiene demasiadas pocas filas (% vs %). Parece un archivo de prueba.', p_importacion_id, v_total_filas_nuevo, v_total_filas_actual;
        RETURN;
    END IF;

    -- Apagar listas anteriores del proveedor
    UPDATE public.listas_precios_proveedor
    SET vigente = false, fecha_vigor_hasta = now()
    WHERE proveedor = v_proveedor
      AND vigente = true
      AND importacion_id <> p_importacion_id;

    -- Encender la nueva lista si tiene al menos un articulo
    IF (SELECT count(*) FROM costos_articulo WHERE importacion_id = p_importacion_id) > 0 THEN
        UPDATE public.listas_precios_proveedor
        SET vigente = true
        WHERE importacion_id = p_importacion_id;
    END IF;
END;

public.upsert_egreso.source_sql:
DECLARE v_norm text; v_tipo text; v_op text; v_art text;
BEGIN
  v_norm := lower(btrim(translate(coalesce(p_tipo_egreso,''), 'ÁÉÍÓÚÜÑáéíóúüñ','AEIOUUNaeiouun')));
  v_tipo := CASE WHEN v_norm='' THEN 'otro'
    WHEN position('venta' in v_norm)>0 THEN 'venta'
    WHEN position('full' in v_norm)>0 OR position('fulfillment' in v_norm)>0 THEN 'envio_full'
    WHEN position('devolucion' in v_norm)>0 OR position('proveedor' in v_norm)>0 THEN 'devolucion_proveedor'
    ELSE 'otro' END;
  v_op  := NULLIF(btrim(coalesce(p_operador_id,'')),'');
  v_art := NULLIF(btrim(coalesce(p_articulo_id,'')),'');
  INSERT INTO egresos (egreso_id,articulo_id,cantidad,guia,transportista,tipo_egreso,notas,fecha,operador_id,largo,ancho,alto,peso)
  VALUES (p_egreso_id, v_art, p_cantidad, p_guia, p_transportista, v_tipo, p_notas, p_fecha, v_op,
    NULLIF(btrim(p_largo),'')::numeric, NULLIF(btrim(p_ancho),'')::numeric,
    NULLIF(btrim(p_alto),'')::numeric, NULLIF(btrim(p_peso),'')::numeric)
  ON CONFLICT (egreso_id) DO UPDATE SET
    articulo_id=EXCLUDED.articulo_id, cantidad=EXCLUDED.cantidad, guia=EXCLUDED.guia,
    transportista=EXCLUDED.transportista, tipo_egreso=EXCLUDED.tipo_egreso, notas=EXCLUDED.notas,
    fecha=EXCLUDED.fecha, operador_id=EXCLUDED.operador_id,
    largo=EXCLUDED.largo, ancho=EXCLUDED.ancho, alto=EXCLUDED.alto, peso=EXCLUDED.peso;
END;

public.claim_precio_recalc.source_sql:
DECLARE
  claimed_ids uuid[];
BEGIN
  SELECT array_agg(id) INTO claimed_ids FROM (
    SELECT id FROM precio_recalc_queue
    WHERE procesado_at IS NULL
    ORDER BY COALESCE(prioridad, 100) ASC, encolado_at ASC
    LIMIT batch_size_limit
    FOR UPDATE SKIP LOCKED
  ) limited;
  IF claimed_ids IS NULL THEN RETURN; END IF;
  RETURN QUERY
  UPDATE precio_recalc_queue
  SET procesado_at = now()
  WHERE id = ANY(claimed_ids)
  RETURNING *;
END;

public.claim_jobs.source_sql:
DECLARE claimed_ids uuid[];
BEGIN
  SELECT array_agg(id) INTO claimed_ids
  FROM (
    SELECT id FROM jobs
    WHERE status = 'pending' AND scheduled_at <= now()
    ORDER BY GREATEST(priority - FLOOR(EXTRACT(EPOCH FROM (now() - scheduled_at)) / 300), 0) ASC, scheduled_at ASC
    LIMIT batch_size_limit
    FOR UPDATE SKIP LOCKED
  ) limited_jobs;
  IF claimed_ids IS NULL THEN RETURN; END IF;
  RETURN QUERY
  UPDATE jobs
     SET status = 'processing',
         attempts = attempts + 1,
         processed_at = now()
   WHERE id = ANY(claimed_ids)
  RETURNING *;
END;

public.procesar_import_job.source_sql:
DECLARE
  v_job public.import_jobs;
BEGIN
  -- Toma un job especifico o el mas antiguo en cola, con lock para evitar doble ejecucion
  IF p_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.import_jobs
      WHERE id = p_job_id AND estado IN ('queued','running')
      FOR UPDATE SKIP LOCKED;
  ELSE
    SELECT * INTO v_job FROM public.import_jobs
      WHERE estado IN ('queued','running')
      ORDER BY created_at
      FOR UPDATE SKIP LOCKED
      LIMIT 1;
  END IF;

  IF v_job.id IS NULL THEN
    RETURN NULL;  -- no hay trabajo disponible
  END IF;

  -- Marca en ejecucion
  UPDATE public.import_jobs
     SET estado='running', intentos=intentos+1, locked_at=now(), updated_at=now()
   WHERE id=v_job.id
   RETURNING * INTO v_job;

  BEGIN
    -- Timeout amplio SOLO para esta transaccion (no depende del gateway HTTP)
    PERFORM set_config('statement_timeout','600000', true); -- 10 min local

    -- Ejecuta el pipeline pesado ya encapsulado
    PERFORM public.fn_preparar_importacion_revision(v_job.importacion_id, v_job.proveedor);

    UPDATE public.import_jobs
       SET estado='done', fase='finalize', cursor_offset=COALESCE(total_items,cursor_offset),
           error_msg=NULL, updated_at=now()
     WHERE id=v_job.id
     RETURNING * INTO v_job;

  EXCEPTION WHEN OTHERS THEN
    UPDATE public.import_jobs
       SET estado = CASE WHEN intentos >= max_intentos THEN 'error' ELSE 'queued' END,
           error_msg = left(SQLERRM, 2000), locked_at=NULL, updated_at=now()
     WHERE id=v_job.id
     RETURNING * INTO v_job;

    IF v_job.estado='error' THEN
      UPDATE public.importaciones_excel SET estado='error' WHERE id=v_job.importacion_id;
    END IF;
  END;

  RETURN v_job;
END;

public.procesar_precio_recalc_queue.source_sql:
DECLARE claimed_ids uuid[]; art_ids text[];
BEGIN
  SELECT array_agg(id), array_agg(DISTINCT articulo_id)
    INTO claimed_ids, art_ids
  FROM ( SELECT id, articulo_id FROM precio_recalc_queue
         WHERE procesado_at IS NULL
         ORDER BY COALESCE(prioridad,100) ASC, encolado_at ASC
         LIMIT batch_size_limit FOR UPDATE SKIP LOCKED ) s;
  IF claimed_ids IS NULL THEN RETURN 0; END IF;
  PERFORM public.fn_recalcular_lote(art_ids);
  UPDATE precio_recalc_queue SET procesado_at = now() WHERE id = ANY(claimed_ids);
  RETURN array_length(claimed_ids,1);
END;

public.encolar_import_job.source_sql:
DECLARE
  v_job_id uuid;
  v_total  integer;
  v_estado text;
BEGIN
  SELECT count(*) INTO v_total FROM public.listas_precios_raw_staging WHERE importacion_id = p_importacion_id;

  SELECT id INTO v_job_id FROM public.import_jobs
   WHERE importacion_id = p_importacion_id AND estado IN ('queued','running') LIMIT 1;
  IF v_job_id IS NOT NULL THEN RETURN v_job_id; END IF;

  INSERT INTO public.import_jobs (importacion_id, proveedor, fase, estado, total_items, cursor_offset)
  VALUES (p_importacion_id, p_proveedor, 'stage_to_raw', 'queued', v_total, 0)
  RETURNING id INTO v_job_id;

  -- Normaliza el estado hacia 'mapeando' respetando transiciones validas
  SELECT estado::text INTO v_estado FROM public.importaciones_excel WHERE id = p_importacion_id;
  IF v_estado = 'error' THEN
    UPDATE public.importaciones_excel SET estado='pendiente_mapeo' WHERE id=p_importacion_id;
    v_estado := 'pendiente_mapeo';
  END IF;
  IF v_estado = 'pendiente_mapeo' THEN
    UPDATE public.importaciones_excel SET estado='mapeando' WHERE id=p_importacion_id;
  END IF;

  RETURN v_job_id;
END;

public.tmp_run_diff_dacb722a.source_sql:
BEGIN
  SET LOCAL statement_timeout = '900000';
  -- Ruta valida de estados: error -> pendiente_mapeo -> mapeando
  UPDATE public.importaciones_excel SET estado='pendiente_mapeo', error_mensaje=NULL, ultima_actividad=now() WHERE id='dacb722a-b261-4103-9b82-e05dcd3c8aa9' AND estado='error';
  UPDATE public.importaciones_excel SET estado='mapeando', ultima_actividad=now() WHERE id='dacb722a-b261-4103-9b82-e05dcd3c8aa9' AND estado='pendiente_mapeo';
  PERFORM public.fn_preparar_importacion_revision('dacb722a-b261-4103-9b82-e05dcd3c8aa9'::uuid, 'Urrea Herramientas');
EXCEPTION WHEN OTHERS THEN
  UPDATE public.importaciones_excel SET estado='error', error_mensaje='tmp_run_diff: '||SQLERRM, ultima_actividad=now() WHERE id='dacb722a-b261-4103-9b82-e05dcd3c8aa9';
END;

public.fn_procesar_precio_recalc_queue.source_sql:
DECLARE q record; m record; n int := 0;
BEGIN
  FOR q IN
    SELECT id, articulo_id FROM precio_recalc_queue
     WHERE procesado_at IS NULL
     ORDER BY prioridad DESC NULLS LAST, encolado_at
     FOR UPDATE SKIP LOCKED
     LIMIT p_batch
  LOOP
    BEGIN
      FOR m IN SELECT publicacion_id FROM mapeo_publicacion_articulo WHERE articulo_id = q.articulo_id LOOP
        BEGIN
          PERFORM fn_recalcular_precio_publicacion(m.publicacion_id);
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'recalc pub % : %', m.publicacion_id, SQLERRM;
        END;
      END LOOP;
      UPDATE precio_recalc_queue SET procesado_at = now() WHERE id = q.id;
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE precio_recalc_queue SET procesado_at = now() WHERE id = q.id;
      RAISE WARNING 'recalc articulo % : %', q.articulo_id, SQLERRM;
    END;
  END LOOP;
  RETURN n;
END

public.fn_preparar_importacion_revision.source_sql:
DECLARE
    v_mapeo         jsonb;
    v_col_modelo    text;
    v_modo          text;
    v_importacion_vieja uuid;
    v_nuevos        int := 0;
    v_eliminados    int := 0;
    v_modificados   int := 0;
    v_totales       int := 0;
    v_resultado     jsonb;
BEGIN
    -- 1) Mover de staging a raw
    SELECT COUNT(*) INTO v_totales
      FROM listas_precios_raw_staging
     WHERE importacion_id = p_importacion_id;

    INSERT INTO listas_precios_raw (importacion_id, proveedor, fila_num, payload, columnas_guardadas)
    SELECT importacion_id, proveedor, fila_num, payload, columnas_guardadas
      FROM listas_precios_raw_staging
     WHERE importacion_id = p_importacion_id;

    DELETE FROM listas_precios_raw_staging
     WHERE importacion_id = p_importacion_id;

    -- 2) Leer el modo de carga
    SELECT modo_carga, mapeo_columnas INTO v_modo, v_mapeo
      FROM importaciones_excel
     WHERE id = p_importacion_id;

    v_modo := COALESCE(v_modo, 'parcial');
    v_col_modelo := v_mapeo->>'columna_modelo';

    -- Buscar cuál es el archivo/lista "vigente" actual para comparar
    SELECT importacion_id INTO v_importacion_vieja
      FROM listas_precios_proveedor
     WHERE proveedor = p_proveedor AND vigente = true
     LIMIT 1;

    IF v_col_modelo IS NULL OR v_importacion_vieja IS NULL THEN
        v_nuevos := v_totales;
    ELSE
        -- NUEVO (s) indexado por modelo
        -- Optimizacion: Usamos md5(payload::text) en lugar de payload completo para el Diff
        CREATE TEMP TABLE tmp_new ON COMMIT DROP AS
        SELECT (payload->>v_col_modelo) AS modelo, md5(payload::text) as phash
        FROM listas_precios_raw
        WHERE importacion_id = p_importacion_id
          AND (payload->>v_col_modelo) IS NOT NULL;
        CREATE INDEX ON tmp_new (modelo);

        -- VIEJO (o) indexado por modelo
        CREATE TEMP TABLE tmp_old ON COMMIT DROP AS
        SELECT (payload->>v_col_modelo) AS modelo, md5(payload::text) as phash
        FROM listas_precios_raw
        WHERE importacion_id = v_importacion_vieja
          AND (payload->>v_col_modelo) IS NOT NULL;
        CREATE INDEX ON tmp_old (modelo);

        ANALYZE tmp_new;
        ANALYZE tmp_old;

        -- NUEVOS: en tmp_new pero no en tmp_old
        SELECT count(*) INTO v_nuevos
        FROM tmp_new n
        WHERE NOT EXISTS (SELECT 1 FROM tmp_old o WHERE o.modelo = n.modelo);

        -- ELIMINADOS: en tmp_old pero no en tmp_new
        IF v_modo = 'full' THEN
            SELECT count(*) INTO v_eliminados
            FROM tmp_old o
            WHERE NOT EXISTS (SELECT 1 FROM tmp_new n WHERE n.modelo = o.modelo);
        ELSE
            v_eliminados := 0;
        END IF;

        -- MODIFICADOS: mismo modelo, distinto payload (comparacion de MD5 ultra rápida)
        SELECT count(*) INTO v_modificados
        FROM tmp_new n
        JOIN tmp_old o ON o.modelo = n.modelo
        WHERE n.phash <> o.phash;
    END IF;

    -- Full mode: marcar vieja no vigente + alta nueva
    IF v_modo = 'full' THEN
        BEGIN
          ALTER TABLE listas_precios_proveedor DISABLE TRIGGER USER;
          UPDATE listas_precios_proveedor SET vigente = false
           WHERE proveedor = p_proveedor AND vigente = true;
          INSERT INTO listas_precios_proveedor (proveedor, importacion_id, vigente, total_filas)
          VALUES (p_proveedor, p_importacion_id, true, v_totales);
          ALTER TABLE listas_precios_proveedor ENABLE TRIGGER USER;
        EXCEPTION WHEN OTHERS THEN
          ALTER TABLE listas_precios_proveedor ENABLE TRIGGER USER;
          RAISE;
        END;
    END IF;

    -- 3) Resolver Costos y Poblarlos
    v_resultado := public.fn_resolver_y_poblar_costos(p_importacion_id, p_proveedor);

    -- Resumen diff + estado en_revision
    UPDATE importaciones_excel
       SET resumen_diff = jsonb_build_object(
             'totales', v_totales,
             'nuevos', v_nuevos,
             'modificados', v_modificados,
             'eliminados', v_eliminados,
             'resolucion', v_resultado
           ),
           estado = 'en_revision'::estado_importacion_excel,
           ultima_actividad = now()
     WHERE id = p_importacion_id;

END;
